UPDATE pois
SET image_url = #{imageUrl}
WHERE id = #{poiId}
  AND status = 1

UPDATE spots
SET cover_image = #{imageUrl}
WHERE id = #{spotId}
  AND status = 1

UPDATE pois p
JOIN spots s ON s.id = #{spotId}
SET p.image_url = #{imageUrl}
WHERE p.status = 1
  AND (
    p.id = s.representative_poi_id
    OR p.id = s.legacy_poi_id
  )

UPDATE foods
SET image_url = #{imageUrl}
WHERE id = #{foodId}
  AND status = 1

UPDATE circles
SET cover_url = #{imageUrl}
WHERE id = #{circleId}
  AND status = 1
